using Flurl;
using Flurl.Http;

class Program
{
    static async Task Main()
    {
        var response = await "https://api.example.com"
            .AppendPathSegment("users")
            .WithOAuthBearerToken("token")
            .PostJsonAsync(new { Name = "Alice", Email = "alice@example.com" });

        var user = await response.GetJsonAsync<User>();
        Console.WriteLine($"Created user: {user.Name}");

        var list = await "https://api.example.com/users"
            .SetQueryParam("page", 1)
            .SetQueryParam("pageSize", 10)
            .GetJsonAsync<List<User>>();
    }
}

public class User { public string Name { get; set; } = string.Empty; }
